  # The first operation that completes against a plain 200: with no
  # arguments, else with every path parameter its points declare filled in.
  defp usable_op do
    plain =
      Smsapi.new(
        S.jm([
          "apikey", @canary.apikey,
          "utility", S.jm(["fetcher", fn _c, _u, _f -> {response(200, S.jm(["id", "i1"]), []), nil} end])
        ])
      )

    Enum.find_value(candidates(), fn {name, acc, op, params} ->
      filled = Map.new(params, fn p -> {p, "p1"} end)

      Enum.find_value([%{}, filled], fn match ->
        try do
          op.(acc.(plain), match, S.jm([]))
          {name, acc, op, match}
        rescue
          _ -> nil
        catch
          _, _ -> nil
        end
      end)
    end)
  end

  # A feature that raises from inside the pipeline, quoting the request it
  # saw: an error make_error never handled.
  defp throw_feature(unexpected) do
    saw = fn ctx -> "hook saw " <> S.jsonify(S.getprop(ctx, "spec")) end

    S.jm([
      "name", "throwhook", "version", "0.0.1", "active", true, "options", S.jm([]),
      "init", fn _ctx, _opts -> nil end,
      "PreResponse", fn ctx -> raise saw.(ctx) end,
      # Fired from the operation's rescue, before its cleaning.
      "PreUnexpected", fn ctx -> if unexpected, do: raise(saw.(ctx)) end
    ])
  end

  # A stream that fails while the caller iterates it, quoting a credential.
  defp stream_feature do
    S.jm([
      "name", "streamthrow", "version", "0.0.1", "active", true, "options", S.jm([]),
      "init", fn _ctx, _opts -> nil end,
      "PreDone", fn ctx ->
        S.setprop(S.getprop(ctx, "result"), "stream",
          fn -> Stream.map([1], fn _ -> raise "stream saw " <> @canary.apikey end) end)
      end
    ])
  end

  # A stream that succeeds, yielding the result's items.
  defp stream_ok_feature do
    S.jm([
      "name", "streamok", "version", "0.0.1", "active", true, "options", S.jm([]),
      "init", fn _ctx, _opts -> nil end,
      "PreDone", fn ctx ->
        result = S.getprop(ctx, "result")
        rd = S.getprop(result, "resdata")
        items = if S.islist(rd), do: Enum.map(H.entries(rd), &elem(&1, 1)), else: List.wrap(rd)
        S.setprop(result, "stream", fn -> items end)
      end
    ])
  end

  # The target operation, streamed through its entity.
  defp stream_of(sdk, {name, acc, _op, match}, callopts) do
    ent = acc.(sdk)
    mod = S.getprop(ent, "_module")
    mod.stream(ent, List.last(String.split(name, ".")), S.jm(["reqmatch", args(match)]), callopts)
  end

  # Features that fail the operation with the SDK's own error, whose code
  # quotes a registered value: one refuses it as rbac does, and records the
  # error PreUnexpected hands a hook; the other raises.
  defp deny_feature(sinks) do
    S.jm([
      "name", "denyhook", "version", "0.0.1", "active", true, "options", S.jm([]),
      "init", fn _ctx, _opts -> nil end,
      "PrePoint", fn ctx ->
        err = Smsapi.Context.make_error(ctx, "denied:" <> @canary.value, "denied")
        S.setprop(S.getprop(ctx, "out"), "point", err)
      end,
      "PreUnexpected", fn ctx ->
        add(sinks, error_forms(S.getprop(S.getprop(ctx, "ctrl"), "err")))
        nil
      end
    ])
  end

  defp raise_feature do
    S.jm([
      "name", "raisehook", "version", "0.0.1", "active", true, "options", S.jm([]),
      "init", fn _ctx, _opts -> nil end,
      "PreResponse", fn _ctx -> raise Smsapi.Error.new("raised:" <> @canary.value, "raised") end
    ])
  end

  defp drive(sdk, {_name, acc, op, match}, ctrl, sinks) do
    ent = acc.(sdk)
    # A caller may keep the record it passed rather than read ctrl.explain.
    held = S.getprop(ctrl, "explain")

    {out, err} =
      try do
        {op.(ent, match, ctrl), nil}
      rescue
        e -> {nil, e}
      end

    if err != nil, do: add(sinks, error_forms(err))
    if out != nil, do: add(sinks, result_forms(out))
    explain = S.getprop(ctrl, "explain")
    if explain != nil, do: add(sinks, data_forms("explain", explain))
    if held != nil and held != explain, do: add(sinks, data_forms("explain:held", held))
    err
  end

  @no_target "no operation of this SDK completes against a plain 200; nothing to sweep"

  # ExUnit has no runtime skip, so a sweep with nothing to drive says so.
  test "no credential leaves the SDK in any form" do
    case usable_op() do
      nil -> IO.puts("SKIP no credential leaves the SDK in any form: " <> @no_target)
      target -> sweep(target)
    end
  end

  test "the sweep can see a leak: clean switched off shows the credential" do
    case usable_op() do
      nil -> IO.puts("SKIP the sweep can see a leak: " <> @no_target)
      target -> sweep_blind(target)
    end
  end

  defp sweep(target) do
    sinks = S.jt([])

    variants = [
      {"throw", fn -> S.jm([]) end},
      {"explain", fn -> S.jm(["explain", S.jm([])]) end},
      {"nothrow", fn -> S.jm(["throw", false, "explain", S.jm([])]) end}
    ]

    {errors, explains} =
      Enum.reduce(scenarios(), {%{}, %{}}, fn {sname, respond}, acc ->
        Enum.reduce(variants, acc, fn {vname, mkctrl}, {errors, explains} ->
          sdk = make_sdk(respond, sinks, [])
          ctrl = mkctrl.()
          err = drive(sdk, target, ctrl, sinks)
          add(sinks, forms("sdk", sdk))
          key = sname <> "/" <> vname
          errors = if err != nil, do: Map.put(errors, key, err), else: errors
          ex = S.getprop(ctrl, "explain")
          explains = if ex != nil, do: Map.put(explains, key, ex), else: explains
          {errors, explains}
        end)
      end)

    # A credential mistyped as a map is rejected by validation, whose message
    # quotes the value it rejected.
    rejected =
      try do
        Smsapi.new(S.jm(["apikey", S.jm(["value", @canary.apikey]), "clean", S.jm(["values", @canary.value])]))
        nil
      rescue
        e -> e
      end

    assert rejected != nil, "a credential mistyped as a map should be rejected"
    add(sinks, forms("rejected", rejected))

    # An error a feature hook raises, quoting the request, skips make_error.
    [{_name, ok} | _] = scenarios()

    for unexpected <- [false, true] do
      hooked = make_sdk(ok, sinks, [], [throw_feature(unexpected)])
      err = drive(hooked, target, S.jm(["explain", S.jm([])]), sinks)
      assert err != nil, "the throwing hook should fail the operation"
    end

    # Iterating a stream runs through the same cleaning path as the operation,
    # and the explain record the caller passed is cleaned however it ends.
    for {name, extra} <- [{"stream", [stream_feature()]}, {"stream-ok", [stream_ok_feature()]}, {"stream-plain", []}] do
      explain = S.jm([])
      callopts = S.jm(["ctrl", S.jm(["explain", explain])])

      streamerr =
        try do
          Enum.to_list(stream_of(make_sdk(ok, sinks, [], extra), target, callopts))
          nil
        rescue
          e -> e
        end

      assert (name == "stream") == (streamerr != nil), name <> ": only the failing stream raises"
      if streamerr != nil, do: add(sinks, forms(name, streamerr))
      assert S.size(explain) > 0, name <> ": the explain record was not filled"
      add(sinks, data_forms(name <> ":explain", explain))
    end

    # A feature's own error keeps its code, which is cleaned like the message:
    # returned, handed to a hook, raised by a hook, and nested in a record.
    denied = drive(make_sdk(ok, sinks, [], [deny_feature(sinks)]), target, S.jm([]), sinks)
    assert denied != nil, "the refusing hook should fail the operation"
    raised = drive(make_sdk(ok, sinks, [], [raise_feature()]), target, S.jm([]), sinks)
    assert raised != nil, "the raising hook should fail the operation"

    nested =
      Smsapi.Utility.clean_impl(Smsapi.get_root_ctx(make_sdk(ok, sinks, [])),
        S.jm(["err", Smsapi.Error.new("nested:" <> @canary.value, "nested")]))

    add(sinks, data_forms("nested", nested))

    # A client given no clean block at all masks by the schema defaults.
    [_ok, {_nf, notfound_respond} | _] = scenarios()

    bare =
      Smsapi.new(
        S.jm([
          "apikey", @canary.apikey,
          "secret", @canary.secret,
          "headers", S.jm(["X-Custom-Token", @canary.header]),
          "utility", S.jm(["fetcher", fn _ctx, url, fd -> notfound_respond.(url, fd) end])
        ])
      )

    barerr = drive(bare, target, S.jm([]), sinks)
    assert barerr != nil, "the 404 scenario must fail without a clean block"

    # The raw path returns its failure rather than raising it.
    [_ok, _nf, _server, {_tr, transport_respond} | _] = scenarios()
    direct = Smsapi.direct(make_sdk(transport_respond, sinks, []), S.jm(["path", "raw"]))
    assert S.getprop(direct, "ok") == false, "a transport failure should fail direct()"
    add(sinks, forms("direct", S.getprop(direct, "err")))

    all = sink_list(sinks)
    leaked = Enum.filter(all, fn s -> leaks(s.text) != [] end)

    IO.puts("clean: swept #{length(all)} surface(s), #{length(leaked)} leak(s)")

    assert leaked == [],
           "credential leaked through: " <>
             Enum.map_join(leaked, "; ", fn s -> s.name <> " [" <> Enum.join(leaks(s.text), ", ") <> "]" end)

    # The positive half: the slot the credential travelled in is masked, and
    # an unregistered token in a response header is masked by name.
    notfound = errors["notfound/throw"]
    assert notfound != nil, "the 404 scenario must throw"
    assert match?(%Smsapi.Error{}, notfound), "the 404 error is an SDK error"
    assert Smsapi.Error.status(notfound) == 404
    spec = notfound.spec

    unless @auth.suppressed do
      case @auth.where do
        "query" ->
          assert header(S.getprop(spec, "query"), @auth.name) == @mask

        "cookie" ->
          assert String.contains?(to_string(header(S.getprop(spec, "headers"), "cookie")), @mask)

        _ ->
          assert String.ends_with?(to_string(header(S.getprop(spec, "headers"), @auth.name)), @mask)
      end
    end

    assert header(S.getprop(spec, "headers"), "x-custom-token") == @mask
    assert denied.code == "denied:" <> @mask
    assert raised.code == "raised:" <> @mask
    assert S.getpath(nested, "err.code") == "nested:" <> @mask
    assert header(S.getprop(barerr.spec, "headers"), "x-custom-token") == @mask

    explained = explains["ok/explain"]
    result = if explained != nil, do: S.getprop(explained, "result"), else: nil
    assert S.ismap(result), "the explain record should carry the result"
    assert header(S.getprop(result, "headers"), "x-session-token") == @mask
  end

  defp sweep_blind(target) do
    sinks = S.jt([])
    [_ok, {_name, notfound} | _] = scenarios()
    sdk = make_sdk(notfound, sinks, [{"active", false}])
    err = drive(sdk, target, S.jm([]), sinks)
    assert err != nil

    # Explaining a failure must not cost it its error.
    explained =
      drive(make_sdk(notfound, S.jt([]), [{"active", false}]), target, S.jm(["explain", S.jm([])]), S.jt([]))

    assert explained != nil and Exception.message(explained) == Exception.message(err),
           "with clean off, explain lost the error"

    assert Enum.any?(sink_list(sinks), fn s -> leaks(s.text) != [] end),
           "with clean off, nothing showed the canary: the sweep is blind"

    unless @auth.suppressed do
      text = S.jsonify(err.spec)

      assert String.contains?(text, @canary.apikey) or
               String.contains?(text, Base.encode64(@canary.apikey <> ":" <> @canary.secret)),
             "the raw spec should carry the credential when clean is off"
    end
  end

  test "a registered value used as a property name is masked, collisions kept" do
    cfg = Smsapi.Utility.make_clean_config(S.jm(["keys", "key,secret,token"]))
    ctx = S.jm(["options", S.jm(["__derived__", S.jm(["clean", cfg])])])
    Smsapi.Utility.clean_add_impl(ctx, "ZZVAL-abc123")
    Smsapi.Utility.clean_add_impl(ctx, "ZZVAL-xyz789")
    out = Smsapi.Utility.clean_impl(ctx, S.jm(["ZZVAL-abc123", 1, "ZZVAL-xyz789", 2, "plain", 3]))
    assert S.getprop(out, @mask) == 1
    assert S.getprop(out, @mask <> "#1") == 2
    assert S.getprop(out, "plain") == 3
    assert "ZZVAL-abc123" not in S.keysof(out)
  end

  # A feature's name is not a field name: a feature called secrets does not
  # make its settings secret, though a sensitive field inside it still is. An
  # entity block, of entity settings or seeded records, is not read at all.
  test "a feature's name is read as a name" do
    record = S.jm(["zztoken", S.jm(["ZZTOKEN01", S.jm(["note", "PLAINRECORD-t5r3e1w9"])])])

    client =
      Smsapi.new(
        S.jm([
          "apikey", @canary.apikey,
          "feature",
          S.jm([
            "secrets", S.jm(["active", false, "name", "ZZNAME-feat123", "token", "ZZTOKEN-feat456"]),
            "test", S.jm(["active", false, "entity", record])
          ]),
          "entity", S.jm(["zztoken", S.jm(["alias", S.jm(["zzkey", "PLAINALIAS-m2n4b6v8"])])])
        ])
      )

    ctx = Smsapi.get_root_ctx(client)
    assert Smsapi.Utility.clean_impl(ctx, "ZZNAME-feat123 ZZTOKEN-feat456") == "ZZNAME-feat123 " <> @mask
    assert Smsapi.Utility.clean_impl(ctx, "record PLAINRECORD-t5r3e1w9") == "record PLAINRECORD-t5r3e1w9"
    assert Smsapi.Utility.clean_impl(ctx, "alias PLAINALIAS-m2n4b6v8") == "alias PLAINALIAS-m2n4b6v8"
  end

  test "the generated config's own clean block is honoured" do
    config = S.jm(["options", S.jm(["clean", S.jm(["keys", "zzsens", "values", "CONFIG-SEEDED-1"])])])
    ctx = S.jm(["config", config, "options", S.jm(["clean", S.jm(["values", "CALLER-SEEDED-2"])])])
    cctx = S.jm(["options", Smsapi.Utility.make_options_impl(ctx)])

    assert Smsapi.Utility.clean_impl(cctx, "a CONFIG-SEEDED-1 b CALLER-SEEDED-2") ==
             "a " <> @mask <> " b " <> @mask

    out = Smsapi.Utility.clean_impl(cctx, S.jm(["my_zzsens", "x", "other", "y"]))
    assert S.getprop(out, "my_zzsens") == @mask
    assert S.getprop(out, "other") == "y"
    assert S.getpath(config, "options.clean.keys") == "zzsens"
    assert S.getpath(config, "options.clean.values") == "CONFIG-SEEDED-1"
  end

  test "clean_add_sensitive registers every scalar under a sensitive name, at any depth" do
    cfg = Smsapi.Utility.make_clean_config(S.jm(["keys", "key,secret,token"]))
    ctx = S.jm(["options", S.jm(["__derived__", S.jm(["clean", cfg])])])

    Smsapi.Utility.clean_add_sensitive(ctx, S.jm([
      "apikey", S.jm(["value", "NESTED-SECRET-1"]),
      "headers", S.jm(["X-Api-Token", S.jt(["LISTED-SECRET-2"])]),
      "secret", 123456789,
      "name", "not-a-secret"
    ]))

    values = Enum.map(H.entries(S.getprop(cfg, "values")), &elem(&1, 1))
    assert "NESTED-SECRET-1" in values
    assert "LISTED-SECRET-2" in values
    assert "123456789" in values
    refute "not-a-secret" in values
  end
end
